package io.github.jasper.monitoring.api.management.command;
import java.util.Objects;
public final class AlertAcknowledgeCommand { private final String alertId,reason; private final long expectedVersion; private AlertAcknowledgeCommand(String id,long version,String reason){if(version<1)throw new IllegalArgumentException("expectedVersion must be positive");this.alertId=require(id);this.reason=require(reason);this.expectedVersion=version;} public static AlertAcknowledgeCommand of(String id,long version,String reason){return new AlertAcknowledgeCommand(id,version,reason);} public String getAlertId(){return alertId;} public long getExpectedVersion(){return expectedVersion;} public String getReason(){return reason;} private static String require(String s){Objects.requireNonNull(s);if(s.trim().isEmpty())throw new IllegalArgumentException("value must not be blank");return s;} }
